svg.script:
(function () {
  const SITE_URL =
    "https://cdn.jsdelivr.net/gh/timmysmathwork/Real-Auto-update@main/updated-site.html";

  const BASE_URL =
    "https://cdn.jsdelivr.net/gh/timmysmathwork/Real-Auto-update@main/";

  const frame = document.getElementById("site");
  const container = document.getElementById("container");
  const status = document.getElementById("status");

  let busy = false;

  async function loadSite() {
    if (busy) return;
    busy = true;

    try {
      const url = new URL(SITE_URL);
      url.searchParams.set("_refresh", Date.now().toString());

      const response = await fetch(url.href, {
        cache: "no-store"
      });

      if (!response.ok) {
        throw new Error("HTTP " + response.status);
      }

      const html = await response.text();

      // Set the base address before the site's own resources.
      const base = '<base href="' + BASE_URL + '">';
      let documentHTML;

      if (/<head\b[^>]*>/i.test(html)) {
        documentHTML = html.replace(
          /<head\b[^>]*>/i,
          function (head) {
            return head + base;
          }
        );
      } else {
        documentHTML =
          "<!doctype html><html><head>" + base +
          "</head><body>" + html + "</body></html>";
      }

      frame.srcdoc = documentHTML;
      container.setAttribute("visibility", "visible");
      status.textContent = "";

    } catch (error) {
      status.textContent = "Load failed: " + error.message;
    } finally {
      busy = false;
    }
  }

  loadSite();
  setInterval(loadSite, 60000);
}());
